// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, uint256 seed) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        bytes32 guess = bytes32(seed);

        vm.deal(actor, 2 ether);

        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);

        vm.roll(block.number + 2);

        bool ok1;
        vm.prank(actor);
        try c.settle() {
            ok1 = true;
        } catch {
            ok1 = false;
        }

        bool ok2;
        vm.prank(actor);
        try c.settle() {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        assertTrue(!ok2);
    }
}
